#include <memory>
#include <iostream>

int main() {
    int stack_var = 42;

    // DANGER: Undefined Behavior (calling delete on stack memory)
    // std::shared_ptr<int> p1(&stack_var);

    // Correct usage for non-heap resources requires a custom deleter
    int* raw_ptr = (int*)std::malloc(sizeof(int));
    *raw_ptr = 10;

    // Custom deleter ensures free() is called, not delete
    std::shared_ptr<int> p2(raw_ptr, [](int* p) {
        std::cout << "Using free()\n";
        std::free(p);
    });
}
